'use strict';
window.HRGrantReady=(async()=>{
 const $=id=>document.getElementById(id),panel=document.createElement('section');panel.id='portalManagement';panel.className='admin-section';document.getElementById('workflowHr').append(panel);
 panel.innerHTML=`<h3>人事權限</h3><p class="muted">保留既有範圍；變更須預覽及模擬再次確認，並非正式 MFA。</p><div class="grant-columns"><section><h4>功能權限</h4><label for="portalTarget">一般人事帳號</label><select id="portalTarget"></select><div id="portalPermissions" class="permission-checks"></div></section><section><h4>資料管理範圍</h4><label for="grantEmployeeMode">員工範圍</label><select id="grantEmployeeMode"><option value="existing">保留既有授權範圍</option><option value="all">全部員工（含後續新增）</option><option value="departments">指定部門</option><option value="employees">指定員工</option></select><button type="button" class="secondary" id="newGrantPlan">建立新的範圍設定</button><div id="grantDepartmentArea" hidden><label>選擇部門</label><div id="grantDepartments" class="permission-checks"></div></div><div id="grantEmployeeArea" hidden><label for="grantEmployeeSearch">搜尋指定員工</label><input id="grantEmployeeSearch"><div id="portalScopeEmployee" class="permission-checks scope-checks"></div></div><label for="grantPeriodMode">考績期別</label><select id="grantPeriodMode"><option value="existing">保留既有期別限制</option><option value="all">全部期別（含後續新增）</option><option value="selected">指定期別</option></select><div id="portalScopePeriod" class="permission-checks" hidden></div><p id="existingGrantSummary" class="muted"></p></section></div><div class="toolbar"><button type="button" id="portalPreviewGrants" class="secondary">預覽授權變更</button><button type="button" id="portalReauth">人事驗證器再次確認</button><button type="button" id="portalSaveGrants" disabled>確認儲存權限</button></div><p id="grantPreview" role="status"></p><p id="portalGrantStatus" role="status"></p>`;
 async function request(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error('操作未完成；請重新預覽、模擬再次確認，並檢查權限。');return data}
 let config=window.HRPortalConfig.normalize(await request('/api/config')),management=await request('/api/portal/management');let plan=null,previewVersion=0,accounts=management.accounts;
 function check(parent,value,label,kind){const l=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=value;box.dataset[kind]=value;l.append(box,document.createTextNode(label));$(parent).append(l);return box}
 for(const [p,label]of [['employee','員工維護與表單分配'],['period','期別及資格管理'],['selfReview','查看考績與年度總覽'],['editReview','退回修改及紙本登記'],['word','Word／Excel 匯出'],['reopen','歸檔狀態調整']])check('portalPermissions',p,label,'permission');
 for(const a of accounts)$('portalTarget').add(new Option(a.id,a.id));
 let optionVersion='';
 async function refreshOptions(){const latest=window.HRPortalConfig.normalize(await request('/api/config')),version=JSON.stringify({employees:latest.employees.map(e=>[e.id,e.name,e.department]),periods:latest.periods,active:latest.activePeriod});if(version===optionVersion)return;const selected=kind=>new Set([...panel.querySelectorAll('[data-'+kind+']:checked')].map(x=>x.value)),departments=selected('department'),employees=selected('employee'),periods=selected('period');config=latest;if($('roleEmployee'))$('roleEmployee').replaceChildren(...config.employees.map(e=>new Option(e.name+' · '+e.id,e.id)));optionVersion=version;previewVersion++;for(const id of ['grantDepartments','portalScopeEmployee','portalScopePeriod'])$(id).replaceChildren();for(const d of [...new Set(config.employees.map(e=>e.department))].sort())check('grantDepartments',d,d,'department').checked=departments.has(d);for(const e of config.employees)check('portalScopeEmployee',e.id,e.name+' · '+e.id,'employee').checked=employees.has(e.id);for(const p of config.periods)check('portalScopePeriod',p,window.HRUI.period(p),'period').checked=periods.has(p);plan=null;$('portalSaveGrants').disabled=true;$('grantPreview').textContent=''}
 await refreshOptions();window.HRGrantRefresh=refreshOptions;document.addEventListener('roster-updated',()=>refreshOptions().catch(e=>$('portalGrantStatus').textContent=e.message));
 function resetPlan(){previewVersion++;plan=null;$('portalSaveGrants').disabled=true;$('grantPreview').textContent='';window.HRManagementDrafts?.dirty.add('portalManagement')}
 function modes(){const mode=$('grantEmployeeMode').value,existing=mode==='existing';$('grantDepartmentArea').hidden=mode!=='departments';$('grantEmployeeArea').hidden=mode!=='employees';$('grantPeriodMode').disabled=existing;if(existing)$('grantPeriodMode').value='existing';else if($('grantPeriodMode').value==='existing')$('grantPeriodMode').value='selected';$('portalScopePeriod').hidden=$('grantPeriodMode').value!=='selected'}
 function load(){previewVersion++;const a=accounts.find(a=>a.id===$('portalTarget').value);if(!a)return;for(const x of panel.querySelectorAll('[data-permission]'))x.checked=a.permissions.includes(x.value);$('grantEmployeeMode').value='existing';$('grantPeriodMode').value='existing';for(const x of panel.querySelectorAll('[data-period]'))x.checked=a.scopes.some(k=>k.period===x.value);for(const x of panel.querySelectorAll('[data-employee]'))x.checked=a.scopes.some(k=>k.employeeId===x.value);$('existingGrantSummary').textContent='目前：'+new Set(a.scopes.map(k=>k.employeeId)).size+' 位員工、'+a.scopes.length+' 筆員工／期別範圍'+(a.scopePolicy?'（動態範圍）':'（既有指定範圍）')+'；預設保留，不自動放寬。';modes();plan=null;$('portalSaveGrants').disabled=true;$('grantPreview').textContent='';if($('grantEmployeeCount'))countEmployees()}
 const roleTools=document.createElement('section');roleTools.className='admin-section';roleTools.innerHTML='<h4>由員工名冊指定一般人事</h4><label for=roleEmployee>員工</label><select id=roleEmployee></select><div class=toolbar><button type=button id=grantHrRole>授予一般人事</button><button type=button id=revokeHrRole class=secondary>撤銷一般人事</button></div><p>不重建員工；新授權功能預設為空，請再於上方設定功能與範圍。需先完成模擬再次確認，異動使舊工作階段失效。</p>';panel.append(roleTools);for(const e of config.employees)$('roleEmployee').add(new Option(e.name+' · '+e.id,e.id));for(const [id,enabled]of [['grantHrRole',true],['revokeHrRole',false]])$(id).onclick=async()=>{if(!await window.HRUI.confirm((enabled?'授予':'撤銷')+'此員工的一般人事角色？舊工作階段將失效。'))return;try{await request('/api/portal/hr-role',{employeeId:$('roleEmployee').value,enabled,confirmed:true});location.reload()}catch(e){$('portalGrantStatus').textContent=e.message}};
 $('portalTarget').onchange=load;load();
 panel.addEventListener('change',e=>{if(e.target.id==='portalTarget')return;modes();resetPlan()});
 $('newGrantPlan').onclick=()=>{$('grantEmployeeMode').value='all';$('grantPeriodMode').value='selected';for(const x of panel.querySelectorAll('[data-period]'))x.checked=x.value===config.activePeriod;modes();resetPlan()};
 const clearEmployees=document.createElement('button');clearEmployees.type='button';clearEmployees.className='secondary';clearEmployees.id='clearGrantEmployees';clearEmployees.textContent='取消指定員工';$('grantEmployeeArea').insertBefore(clearEmployees,$('portalScopeEmployee'));const selectedEmployees=document.createElement('p');selectedEmployees.id='grantEmployeeCount';selectedEmployees.className='muted';$('grantEmployeeArea').append(selectedEmployees);function countEmployees(){selectedEmployees.textContent='已指定 '+panel.querySelectorAll('#portalScopeEmployee input:checked').length+' 人（搜尋不會取消其他勾選）'}clearEmployees.onclick=()=>{for(const x of panel.querySelectorAll('#portalScopeEmployee input'))x.checked=false;countEmployees();resetPlan()};panel.addEventListener('change',countEmployees);countEmployees();
 $('grantEmployeeSearch').oninput=()=>{for(const l of $('portalScopeEmployee').children)l.hidden=!l.textContent.includes($('grantEmployeeSearch').value)};
 function body(){const values=kind=>[...panel.querySelectorAll('[data-'+kind+']:checked')].map(x=>x.value);const employeeMode=$('grantEmployeeMode').value;return {targetId:$('portalTarget').value,permissions:values('permission'),policy:employeeMode==='existing'?{employeeMode:'existing',periodMode:'existing'}:{employeeMode,departments:employeeMode==='departments'?values('department'):[],employeeIds:employeeMode==='employees'?values('employee'):[],periodMode:$('grantPeriodMode').value,periods:$('grantPeriodMode').value==='selected'?values('period'):[]}}}
 $('portalPreviewGrants').onclick=async()=>{try{const proposal=body(),version=++previewVersion,result=await request('/api/portal/grant-preview',proposal);if(version!==previewVersion||JSON.stringify(proposal)!==JSON.stringify(body()))return;plan={proposal,...result};$('grantPreview').textContent='預計授予 '+result.permissions.length+' 項功能，涵蓋 '+result.employeeCount+' 位員工／'+result.scopeCount+' 筆員工期別。'+(proposal.policy.employeeMode==='existing'?'保留原範圍。':'僅在確認儲存後生效；全部／部門範圍會隨名冊更新。');$('grantPreview').textContent+=' 功能：'+result.permissions.map(p=>panel.querySelector('[data-permission="'+p+'"]').parentElement.textContent.trim()).join('、')+'。期別：'+[...new Set(result.scopes.map(k=>k.period))].join('、')+'。';$('portalSaveGrants').disabled=false}catch(e){$('portalGrantStatus').textContent=e.message}};
 $('portalReauth').onclick=async()=>{if(window.HRPortalContext.identitySource==='oidc'){HRGoogleNavigate('/auth/reauth');return}if(!await window.HRUI.confirm('這只是虛構最高人事的再次確認，不是真實密碼或 MFA。確定繼續？'))return;try{await request('/api/portal/reauth',{confirmation:'MOCK-REAUTH'});$('portalGrantStatus').textContent='模擬確認完成，90 秒內可儲存一次授權。'}catch(e){$('portalGrantStatus').textContent=e.message}};
 $('portalSaveGrants').onclick=async()=>{if(!plan||$('portalSaveGrants').disabled||!await window.HRUI.confirm($('grantPreview').textContent+' 確認儲存？'))return;$('portalSaveGrants').disabled=true;try{const result=await request('/api/portal/grant-save',{...plan.proposal,version:plan.version,confirmed:true});accounts=accounts.map(a=>a.id===result.account.id?result.account:a);window.HRManagementDrafts?.clear('portalManagement');load();$('portalGrantStatus').textContent='已儲存模擬授權；異動紀錄 '+result.audit.length+' 筆。下次操作立即重新檢查權限。'}catch(e){plan=null;$('portalSaveGrants').disabled=true;$('portalGrantStatus').textContent=e.message}};
})();
